diff --git a/src/rates.js b/src/rates.js
index 5f91eed..4a73d4d 100644
--- a/src/rates.js
+++ b/src/rates.js
@@ -1,4 +1,12 @@
 // fetchRate(currency) -> Promise<number>; `now` is injectable for testing.
+const cache = new Map();
+
 export async function getExchangeRate(currency, fetchRate, now = Date.now) {
-  return fetchRate(currency);
+  const entry = cache.get(currency);
+  if (entry && now() - entry.timestamp < 60_000) {
+    return entry.rate;
+  }
+  const rate = await fetchRate(currency);
+  cache.set(currency, { rate, timestamp: now() });
+  return rate;
 }

