diff --git a/src/settings.js b/src/settings.js
index 5641036..ed08eb4 100644
--- a/src/settings.js
+++ b/src/settings.js
@@ -1,3 +1,13 @@
 export function cloneSettings(settings) {
-  throw new Error('Not implemented');
+  if (settings === null || typeof settings !== 'object') return settings;
+  if (settings instanceof Date) return new Date(settings.getTime());
+  if (settings instanceof Map) {
+    const copy = new Map();
+    for (const [k, v] of settings) copy.set(cloneSettings(k), cloneSettings(v));
+    return copy;
+  }
+  if (Array.isArray(settings)) return settings.map(cloneSettings);
+  const copy = Object.create(Object.getPrototypeOf(settings));
+  for (const key of Object.keys(settings)) copy[key] = cloneSettings(settings[key]);
+  return copy;
 }

